ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	message: "Flight " ++ (vars.flightId as String) ++ " updated successfully",
	updatedFlight: {
		ID: payload[0].ID,
		code: payload[0].code1,
		price: payload[0].price default 0,
		departureDate: payload[0].takeOffDate as String default "",
		origin: payload[0].fromAirport default "",
		destination: payload[0].toAirport default "",
		emptySeats: payload[0].seatsAvailable default 0,
		plane: {
			"type": payload[0].planeType default "",
			totalSeats: payload[0].totalSeats default 0
		}
	},
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "VALIDATION_ERROR",
	error: "MISSING_REQUIRED_FIELDS",
	message: "Flight creation failed due to missing required fields",
	requiredFields: ["code", "origin", "destination"],
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "DUPLICATE_CODE_ERROR",
	error: "FLIGHT_CODE_EXISTS",
	message: "Flight with the provided code already exists",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
	status: "DATABASE_ERROR",
	error: "DATABASE_OPERATION_FAILED",
	message: "An error occurred while creating the flight record. Please try again later.",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}
